<?php
namespace ServSys\FlatRate;
use ServSys\Inventory\InventoryItemRepository;
if ( ! defined( 'ABSPATH' ) ) { exit; }
final class FlatRateService {
 private $configs; private $categories; private $items; private $materials; private $inventory;
 public function __construct(FlatRateConfigRepository $configs=null,FlatRateCategoryRepository $categories=null,FlatRateItemRepository $items=null,FlatRateMaterialRepository $materials=null,InventoryItemRepository $inventory=null){$this->configs=$configs?:new FlatRateConfigRepository();$this->categories=$categories?:new FlatRateCategoryRepository();$this->items=$items?:new FlatRateItemRepository();$this->materials=$materials?:new FlatRateMaterialRepository();$this->inventory=$inventory?:new InventoryItemRepository();}
 public function save_config(array $data): void {$numeric=array('labor_rate','additional_repair_multiplier','agreement_repair_multiplier','commercial_multiplier','part_markup_multiplier','sales_tax_percent','special_item_low_price','special_item_high_price','special_item_high_hours');$clean=array();foreach($numeric as $key){$clean[$key]=round((float)($data[$key]??0),4);if($clean[$key]<0){throw new \InvalidArgumentException('Flat Rate configuration values cannot be negative.');}}$now=current_time('mysql',true);$user=get_current_user_id();$clean['updated_at']=$now;$clean['updated_by']=$user?:null;if(!$this->configs->current()){$clean['created_at']=$now;$clean['created_by']=$user?:null;}if(!$this->configs->save($clean)){throw new \RuntimeException('Unable to save Flat Rate configuration.');}}
 public function save_category(array $data,int $id=0): int {$name=sanitize_text_field($data['name']??'');if(''===$name){throw new \InvalidArgumentException('Category name is required.');}$clean=array('name'=>$name,'sort_order'=>(int)($data['sort_order']??0),'active'=>!empty($data['active'])?1:0,'updated_at'=>current_time('mysql',true),'updated_by'=>get_current_user_id()?:null);if($id){if(!$this->categories->find($id)){throw new \InvalidArgumentException('Flat Rate category does not belong to the current company.');}if(!$this->categories->update($id,$clean)){throw new \RuntimeException('Unable to save Flat Rate category.');}return $id;}$clean['created_at']=$clean['updated_at'];$clean['created_by']=$clean['updated_by'];$id=$this->categories->create($clean);if(!$id){throw new \RuntimeException('Unable to create Flat Rate category.');}return $id;}
 public function save_item(array $data,int $id=0): int {$code=absint($data['code']??0);$description=sanitize_text_field($data['description']??'');$category_id=absint($data['category_id']??0);if(!$code||''===$description){throw new \InvalidArgumentException('Flat Rate code and description are required.');}if($category_id&&!$this->categories->find($category_id)){throw new \InvalidArgumentException('Flat Rate category does not belong to the current company.');}$existing=$this->items->find_by_code($code);if($existing&&(!$id||(int)$existing['id']!==$id)){throw new \InvalidArgumentException('Flat Rate code already exists for this company.');}$hours=round((float)($data['labor_hours']??0),4);if($hours<0){throw new \InvalidArgumentException('Labor hours cannot be negative.');}$clean=array('category_id'=>$category_id?:null,'code'=>$code,'description'=>$description,'customer_notes'=>sanitize_textarea_field($data['customer_notes']??''),'labor_hours'=>$hours,'no_discount'=>!empty($data['no_discount'])?1:0,'special_item'=>!empty($data['special_item'])?1:0,'active'=>!empty($data['active'])?1:0,'updated_at'=>current_time('mysql',true),'updated_by'=>get_current_user_id()?:null);if($id){if(!$this->items->find($id)){throw new \InvalidArgumentException('Flat Rate item does not belong to the current company.');}if(!$this->items->update($id,$clean)){throw new \RuntimeException('Unable to save Flat Rate item.');}return $id;}$clean['created_at']=$clean['updated_at'];$clean['created_by']=$clean['updated_by'];$id=$this->items->create($clean);if(!$id){throw new \RuntimeException('Unable to create Flat Rate item.');}return $id;}
 public function replace_materials(int $item_id,array $rows): void {if(!$this->items->find($item_id)){throw new \InvalidArgumentException('Flat Rate item does not belong to the current company.');}$clean=array();foreach($rows as $row){$inventory_id=absint($row['inventory_item_id']??0);$description=sanitize_text_field($row['manual_description']??'');$qty=round((float)($row['quantity']??0),4);$cost=isset($row['manual_unit_cost'])&&''!==$row['manual_unit_cost']?round((float)$row['manual_unit_cost'],4):null;if(!$inventory_id&&''===$description){continue;}if($qty<=0){throw new \InvalidArgumentException('Material quantity must be greater than zero.');}if($inventory_id&&!$this->inventory->find($inventory_id)){throw new \InvalidArgumentException('Flat Rate material inventory item does not belong to the current company.');}if(null!==$cost&&$cost<0){throw new \InvalidArgumentException('Manual material cost cannot be negative.');}$clean[]=array('inventory_item_id'=>$inventory_id?:null,'quantity'=>$qty,'manual_description'=>$inventory_id?null:$description,'manual_unit_cost'=>$inventory_id?null:$cost);}$wpdb=$GLOBALS['wpdb'];/* phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching -- Recipe replacement must be atomic. */$wpdb->query('START TRANSACTION');try{if(!$this->materials->delete_for_item($item_id)){throw new \RuntimeException('Unable to replace Flat Rate materials.');}$now=current_time('mysql',true);$user=get_current_user_id();foreach($clean as $sort=>$row){$row['flat_rate_item_id']=$item_id;$row['sort_order']=$sort;$row['created_at']=$now;$row['updated_at']=$now;$row['created_by']=$user?:null;$row['updated_by']=$user?:null;if(!$this->materials->create($row)){throw new \RuntimeException('Unable to save Flat Rate material.');}}/* phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching -- Recipe replacement must be atomic. */$wpdb->query('COMMIT');}catch(\Throwable $e){/* phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching -- Roll back partial recipe replacement. */$wpdb->query('ROLLBACK');throw $e;}}
}
